const changes = $input.first().json.changed || [];
if (changes.length === 0) return [];

// AI-Insights aus dem Aggregations-Node holen
const teamData = {};
try {
  $('Aggregiere zu Teams').all().forEach(i => {
    teamData[i.json.team_name] = i.json.ai_insights || [];
  });
} catch(e) {}

let message = '🚨 *NBA INJURY ALERT*\n';
message += `_${new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit' })} Uhr_\n`;
message += '━━━━━━━━━━━━━━━━\n\n';

changes.forEach(c => {
  const dir  = c.diff > 0 ? '📈 Verschlechtert' : '📉 Verbessert';
  const icon = c.diff > 0 ? '🔴' : '🟢';
  message += `${icon} *${c.team_name}*\n`;
  message += `  ${dir}: ${c.old_score ?? 'neu'} → ${c.new_score} (${c.diff > 0 ? '+' : ''}${c.diff})\n`;
  if (c.key_absences?.length > 0) {
    message += `  Ausfälle: ${c.key_absences.join(', ')}\n`;
  }
  const insights = teamData[c.team_name] || [];
  if (insights.length > 0) {
    message += `  🤖 KI-Einschätzung:\n`;
    insights.slice(0, 2).forEach(ins => message += `    • ${ins}\n`);
  }
  message += '\n';
});

return [{ json: { message } }];

const STAR_WEIGHTS = {
  "Nikola Jokic": 10, "Luka Doncic": 10, "Giannis Antetokounmpo": 10,
  "Shai Gilgeous-Alexander": 10, "Joel Embiid": 10, "Victor Wembanyama": 10,
  "Jayson Tatum": 9, "Anthony Davis": 9, "LeBron James": 9,
  "Kevin Durant": 9, "Stephen Curry": 9, "Zion Williamson": 9,
  "Devin Booker": 8, "Jaylen Brown": 8, "Jalen Brunson": 8,
  "Donovan Mitchell": 8, "Tyrese Haliburton": 8, "Jimmy Butler": 8,
  "Paolo Banchero": 8, "LaMelo Ball": 8, "Karl-Anthony Towns": 8,
  "Kawhi Leonard": 8, "Tyrese Maxey": 8, "Evan Mobley": 8,
  "Trae Young": 8, "Domantas Sabonis": 8, "De'Aaron Fox": 8, "Ja Morant": 8,
  "Franz Wagner": 7, "Cade Cunningham": 7, "Jaren Jackson Jr.": 7,
  "Tyler Herro": 7, "DeMar DeRozan": 7, "James Harden": 7,
  "Jarrett Allen": 6, "Trey Murphy III": 6, "OG Anunoby": 6
};

const STATUS_MULTIPLIER = {
  "Out": 1.0,
  "Doubtful": 0.75,
  "Questionable": 0.5,
  "Day-To-Day": 0.35,
  "Probable": 0.15
};

const AI_HINT_PATTERN = /(surgery|fracture|torn|tear|crutches|out indefinitely|season-ending|miss the remainder|re-?evaluat|did not practice|swelling|limping|cleared|full practice|making good progress|approved to participate|injection|week-to-week)/i;
const FAST_LANE_PATTERN = /(is|has been|was|will be|remains)?\s*(ruled out|listed as out|out for|questionable for|probable for|won't play|will not play)/i;

const injuryData = $input.first().json;
const result = [];

for (const team of injuryData.injuries || []) {
  for (const inj of team.injuries || []) {
    const player = inj.athlete?.displayName || 'Unknown';
    const status = inj.status || 'Unknown';
    const comment = inj.shortComment || '';
    const normalized = comment.trim();
    const baseWeight = STAR_WEIGHTS[player] || 1.5;
    const multi = STATUS_MULTIPLIER[status] ?? 0.4;
    const baseImpact = Number((baseWeight * multi).toFixed(2));
    const hasStrongSignal = AI_HINT_PATTERN.test(normalized);
    const isStarOrHighImpact = baseImpact > 5;
    const isBoilerplate = FAST_LANE_PATTERN.test(normalized) && !hasStrongSignal;
    const needsAi = isStarOrHighImpact || (normalized.length > 0 && hasStrongSignal && !isBoilerplate);

    result.push({
      json: {
        team_name: team.displayName,
        player,
        player_name: player,
        status,
        short_comment: comment,
        shortComment: comment,
        base_weight: baseWeight,
        base_impact: baseImpact,
        needs_ai: needsAi,
        fast_lane_reason: needsAi ? null : 'Fast-Lane: Status/Basis-Impact reichen aus'
      }
    });
  }
}

return result;

const j = $input.first().json;

function extractJsonObject(raw) {
  const cleaned = String(raw || '{}').replace(/```json|```/gi, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  return match ? match[0] : '{}';
}

let aiData = { ai_adjustment: 1.0, ai_reason: 'Keine Analyse' };
try {
  const raw = j.text || j.output || j.response || j.content || '{}';
  aiData = JSON.parse(extractJsonObject(raw));
} catch (e) {}

const adj = Math.min(Math.max(Number(aiData.ai_adjustment) || 1.0, 0.7), 1.5);

return [{ json: {
  ...j,
  ai_adjustment: adj,
  ai_reason: aiData.ai_reason || 'Keine Begruendung',
  final_impact: Number((j.base_impact * adj).toFixed(2))
}}];

const item = $input.first().json;
return [{ json: {
  ...item,
  ai_adjustment: 1.0,
  ai_reason: item.fast_lane_reason || null,
  final_impact: item.base_impact
}}];

const players = $input.all()
  .map(i => i.json)
  .filter(p => p && typeof p === 'object' && p.team_name && p.player);

const teams = {};

for (const p of players) {
  if (!teams[p.team_name]) {
    teams[p.team_name] = { team_name: p.team_name, players: [] };
  }
  teams[p.team_name].players.push(p);
}

return Object.values(teams).map(t => ({ json: t }));

// ─────────────────────────────────────────────────────────────────────────────
// PROBLEM: Qwen 3.5 (und andere "thinking"-Modelle) schicken vor der eigentlichen
// Antwort eine Gedankenkette im Format:
//   "Thinking Process...\n{...json...}"
// oder:
//   "<think>...</think>\n{...json...}"
//
// n8n versucht den kompletten String als JSON zu parsen → Fehler:
//   "Unexpected token T, Thinking P is not valid JSON"
//
// LÖSUNG: Wir suchen mit Regex nach dem ersten { und letzten }
// und extrahieren nur diesen Teil als JSON-String.
// ─────────────────────────────────────────────────────────────────────────────

return $input.all().map(item => {

  // Der AI-Node gibt sein Ergebnis im Feld "text" oder "output" zurück.
  // Wir probieren beide Felder — je nach n8n-Version kann es unterschiedlich heißen.
  const rawText = item.json.text || item.json.output || item.json.message || '';

  // ── Schritt 1: <think>-Block entfernen ─────────────────────────────────────
  // Manche Modelle wrappen ihre Gedanken in <think>...</think> Tags.
  // \s* = beliebig viele Whitespace-Zeichen (auch Zeilenumbrüche)
  // [\s\S]*? = beliebig viele Zeichen (auch Zeilenumbrüche), nicht-gierig (?
  //   bedeutet: so wenig wie möglich matchen, nicht so viel wie möglich)
  const withoutThinkTags = rawText.replace(/<think>[\s\S]*?<\/think>/gi, '');

  // ── Schritt 2: JSON-Block mit Regex isolieren ───────────────────────────────
  // Wir suchen nach dem ERSTEN { und dem LETZTEN } im Text.
  //
  // Regex-Erklärung: /\{[\s\S]*\}/
  //   \{        = literales öffnendes {  (muss escaped werden, da { in Regex Bedeutung hat)
  //   [\s\S]*   = beliebig viele Zeichen INKLUSIVE Zeilenumbrüchen
  //               (\s = Whitespace, \S = kein Whitespace → zusammen = ALLES)
  //               Das normale . matcht keine Zeilenumbrüche, daher dieser Trick
  //   \}        = literales schließendes }
  //
  // Ohne das 'g'-Flag findet match() den ersten Treffer und gibt ihn zurück.
  // Ohne das '?'-Flag ist der Ausdruck "gierig" (greedy): er matched vom ersten {
  // bis zum LETZTEN } — genau was wir wollen bei verschachteltem JSON.
  const jsonMatch = withoutThinkTags.match(/\{[\s\S]*\}/);

  // ── Schritt 3: Parsen oder Fallback ────────────────────────────────────────
  if (jsonMatch) {
    // jsonMatch[0] = der gesamte gematchte String (erstes Element beim non-g match)
    const jsonString = jsonMatch[0];

    try {
      // JSON.parse() konvertiert den String in ein echtes JavaScript-Objekt.
      // Danach kann n8n auf die Felder direkt zugreifen: $json.ai_adjustment
      const parsed = JSON.parse(jsonString);

      // Sicherheitsnetz: ai_adjustment muss eine Zahl zwischen 0.5 und 1.5 sein.
      // Falls das Modell einen unplausiblen Wert ausgibt (z.B. 5.0), clampen wir ihn.
      // Math.max/min ist ein klassischer Clamp-Trick: Math.max(min, Math.min(max, value))
      const adjustment = typeof parsed.ai_adjustment === 'number'
        ? Math.max(0.5, Math.min(1.5, parsed.ai_adjustment))
        : 1.0;

      return {
        json: {
          // Alle bisherigen Felder des Items behalten (Spielername, Status etc.)
          ...item.json,
          // Geparste Felder überschreiben/ergänzen
          ai_adjustment: adjustment,
          ai_reason:     parsed.ai_reason || 'kein Grund angegeben',
          // Debug-Feld: zeigt was das Modell wirklich geschickt hat
          // Nützlich wenn man nachvollziehen will warum ein Wert gesetzt wurde
          _raw_ollama_json: jsonString
        }
      };

    } catch (parseError) {
      // JSON.parse hat einen Fehler geworfen — der extrahierte String ist
      // kein valides JSON (z.B. abgeschnitten, Sonderzeichen etc.)
      // Wir loggen den Fehler und setzen Fallback-Werte.
      return {
        json: {
          ...item.json,
          ai_adjustment: 1.0,
          ai_reason:     `JSON-Parse-Fehler: ${parseError.message}`,
          _parse_error:  true,
          _raw_text:     rawText.slice(0, 200)  // nur erste 200 Zeichen für Debug
        }
      };
    }

  } else {
    // Kein { } gefunden im Ollama-Output — das Modell hat kein JSON zurückgegeben.
    // Mögliche Ursachen: Modell antwortet auf Deutsch/Englisch statt JSON,
    // oder der Output ist leer weil Ollama Timeout hatte.
    return {
      json: {
        ...item.json,
        ai_adjustment: 1.0,  // neutraler Wert: keine Anpassung
        ai_reason:     'Kein JSON in Ollama-Antwort gefunden — Fallback 1.0',
        _parse_error:  true,
        _raw_text:     rawText.slice(0, 200)
      }
    };
  }
});
